export function translateContent(s) {
  if (!s) return s;
  const hit = CONTENT_ES[s];
  if (hit) return hit;
  for (const [re, tpl] of PATTERN_ES) {
    if (re.test(s)) return s.replace(re, tpl);
  }
  return s;
}
